mapper.select:
SELECT 
FROM growth_code_artifact
WHERE user_id = #{userId}
  AND provider = #{provider}
  AND artifact_type = #{artifactType}
  AND repository = #{repository}
  AND external_id = #{externalId}
LIMIT 1

SELECT 
FROM growth_code_artifact
WHERE user_id = #{userId}
  AND deleted = 0
ORDER BY verified_at DESC, id DESC
LIMIT #{limit}

mapper.update:
UPDATE growth_code_artifact
SET deleted = 1,
    update_time = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted = 0

mapper.select:
SELECT 
FROM growth_code_artifact
WHERE user_id = #{userId}
  AND (
        #{afterUpdateTime} IS NULL
        OR update_time > #{afterUpdateTime}
        OR (update_time = #{afterUpdateTime} AND id > #{afterSourceId})
  )
ORDER BY update_time ASC, id ASC
LIMIT #{limit}

SELECT DISTINCT user_id
FROM growth_code_artifact
WHERE update_time >= #{updatedAfter}
ORDER BY user_id ASC
LIMIT #{limit}
